import {
  Entity,
  Column,
  PrimaryGeneratedColumn,
  Unique,
  OneToMany,
  OneToOne,
  CreateDateColumn,
  UpdateDateColumn,
  Index,
} from 'typeorm';
import { Plan } from 'src/plans/entities/plan.entity';
import { TokenUsageHistory } from 'src/tokens/entities/token-usage-history.entity';
import { Payment } from 'src/payments/entities/payment.entity';
import { Salt } from 'src/salt/entities/salt.entity';
import { UserSettings } from './user-settings.entity';
import { UserSkippedVersion } from 'src/notifications/entities/user-skipped-version.entity';
import { UserSession } from 'src/auth/entities/user-session.entity';
import { SupportMessage } from 'src/support/entities/support-message.entity';
import { DialogsStat } from '../../diary-statistics/entities/dialogs-stat.entity';
import { EntriesStat } from '../../diary-statistics/entities/entries-stat.entity';
import { CheckinsStat } from '../../diary-statistics/entities/checkins-stat.entity';
import { CheckinDialogsStat } from '../../diary-statistics/entities/checkin-dialogs-stat.entity';
import { UserReadNotification } from 'src/notifications/entities/user-read-notification';
import { AiModelAnswerReview } from 'src/ai/entities/ai-model-answer-review.entity';
import { RegenerateAiModelAnswer } from 'src/ai/entities/regenerate-ai-model-answer.entity';
import { PositiveNegativeAiModelAnswer } from 'src/ai/entities/positive-negative-ai-model-answer.entity';
import { Font, Role } from '../types';
import { UserAiPreferences } from 'src/ai/entities/user-ai-preferences.entity';
import { AcquisitionSource } from '../types';
import { GoalsStat } from 'src/goals-statistics/entities/goals-stat.entity';
import { UserMonitoring } from 'src/user-monitoring/entities/user-monitoring.entity';
import { ForumPublicProfile } from '../../forum/entities/forum-public-profile.entity';
import { ForumComment } from '../../forum/entities/forum-comment.entity';
import { ForumTopicReadState } from 'src/forum/entities/forum-topic-read-state.entity';
import { ForumNotification } from '../../forum/entities/forum-notification.entity';
import { ForumReaction } from '../../forum/entities/forum-reaction.entity';
import { ForumTopic } from '../../forum/entities/forum-topic.entity';
import { ForumBookmark } from '../../forum/entities/forum-bookmark.entity';
import { ForumReport } from '../../forum/entities/forum-report.entity';
import { ForumModerationLog } from '../../forum/entities/forum-moderation-log.entity';
import { ForumMention } from '../../forum/entities/forum-mention.entity';
import { ForumView } from 'src/forum/entities/forum-view.entity';
import { ForumConversation } from '../../forum/entities/forum-conversation.entity';
import { ForumMessage } from '../../forum/entities/forum-message.entity';
import { ForumUserBlock } from '../../forum/entities/forum-user-block.entity';
import { ForumTopicWatcher } from '../../forum/entities/forum-topic-watcher.entity';
import { UserActivityStats } from '../../user-statistics/entities/user-activity-stat.entity';
import { SubscriptionRuntime } from 'src/subscriptions/types';

@Entity('users')
@Unique(['email'])
@Unique(['phone'])
export class User {
  @PrimaryGeneratedColumn()
  id: number;

  @Column({ unique: true })
  uuid: string;

  @Column({ type: 'varchar', length: 255, unique: true })
  hash: string;

  @Column({ type: 'varchar', length: 255, nullable: true, unique: true })
  email: string | null;

  @Column({ type: 'varchar', length: 32, nullable: true })
  phone: string | null;

  @Column({ type: 'varchar', length: 64, nullable: true })
  oauthProvider: string | null;

  @Column({ type: 'varchar', length: 128, nullable: true })
  oauthProviderId: string | null;

  @Column({ type: 'varchar', length: 255, nullable: true })
  password: string | null;

  @Column({ type: 'varchar', length: 255, nullable: true })
  name: string;

  @Column({ type: 'varchar', length: 255, default: Role.USER })
  role: Role;

  @Column({ type: 'boolean', default: false })
  isRegistered: boolean;

  @Column({ type: 'boolean', default: false })
  usesWithoutSubscription: boolean;

  @Index('idx_users_subscription_runtime')
  @Column({
    name: 'subscription_runtime',
    type: 'varchar',
    default: SubscriptionRuntime.LEGACY_COMPAT,
  })
  subscriptionRuntime: SubscriptionRuntime;

  @Column({ type: 'boolean', default: false })
  isLogged: boolean;

  @Column({ nullable: true, type: 'text' })
  passwordResetCode: string | null;

  @Column({ nullable: true, type: 'text' })
  passwordChangeToken?: string | null;

  @Column({ default: false })
  emailVerified: boolean;

  @Column({ nullable: true, type: 'text' })
  emailVerificationCode: string | null;

  @Column({ nullable: true, type: 'text' })
  phoneVerificationCode: string | null;

  @Column({ nullable: true, type: 'text' })
  deleteAccountVerificationCode: string | null;

  @Column({ nullable: true, type: 'text' })
  resetPinVerificationCode: string | null;

  @Column({ type: 'varchar', length: 255, nullable: true })
  newEmail: string | null;

  @Column({ nullable: true, type: 'text' })
  newEmailVerificationCode: string | null;

  @Column({ type: 'bytea', nullable: true })
  dekEncrypted?: Buffer | null;

  @Column({ type: 'int', default: 1 })
  dekVersion!: number;

  @Column({
    type: 'varchar',
    length: 255,
    default: AcquisitionSource.ORGANIC,
    nullable: true,
  })
  acquisitionSource: string | null;

  @Column({ type: 'jsonb', nullable: true, default: () => "'{}'::jsonb" })
  acquisitionMetaJson: Record<string, any> | null;

  @Column({ name: 'is_system', type: 'boolean', default: false })
  isSystem: boolean;

  @OneToOne(() => UserSettings, (userSettings) => userSettings.user)
  settings: UserSettings;

  @OneToOne(() => UserMonitoring, (monitoring) => monitoring.user)
  monitoring: UserMonitoring;

  @OneToMany(() => UserSession, (session) => session.user)
  sessions: UserSession[];

  @OneToMany(() => DialogsStat, (dialog) => dialog.user)
  dialogsStats: DialogsStat[];

  @OneToMany(() => CheckinsStat, (checkin) => checkin.user)
  checkinsStats: CheckinsStat[];

  @OneToMany(() => CheckinDialogsStat, (dialog) => dialog.user)
  checkinDialogsStats: CheckinDialogsStat[];

  @OneToMany(() => GoalsStat, (goal) => goal.user)
  goalsStats: GoalsStat[];

  @OneToMany(() => EntriesStat, (entry) => entry.user)
  entriesStats: EntriesStat[];

  @OneToMany(() => UserActivityStats, (activity) => activity.user)
  activityStats: UserActivityStats[];

  @OneToMany(() => Plan, (plan) => plan.user)
  plans: Plan[];

  @OneToMany(() => SupportMessage, (message) => message.user)
  supportMessages: SupportMessage[];

  @OneToOne(() => Salt, (salt) => salt.user)
  salt: Salt;

  @Column({ nullable: true })
  regionCode: string;

  @OneToMany(
    () => TokenUsageHistory,
    (tokenUsageHistory) => tokenUsageHistory.user,
  )
  tokenUsageHistory: TokenUsageHistory[];

  @OneToMany(() => UserSkippedVersion, (version) => version.user)
  skippedVersions: UserSkippedVersion[];

  @OneToMany(() => UserReadNotification, (read) => read.user)
  readNotifications: UserReadNotification[];

  @OneToMany(() => Payment, (payment) => payment.user)
  payments: Payment[];

  @OneToMany(() => AiModelAnswerReview, (review) => review.user)
  aiModelAnswerReview: AiModelAnswerReview[];

  @OneToMany(() => RegenerateAiModelAnswer, (regenerate) => regenerate.user)
  regenerateAiModelAnswers: RegenerateAiModelAnswer[];

  @OneToMany(
    () => PositiveNegativeAiModelAnswer,
    (positiveNegative) => positiveNegative.user,
  )
  positiveNegativeAiModelAnswers: PositiveNegativeAiModelAnswer[];

  @OneToOne(() => UserAiPreferences, (p) => p.user, {
    cascade: true,
  })
  aiPreferences!: UserAiPreferences;

  @OneToOne(() => ForumPublicProfile, (profile) => profile.user)
  forumPublicProfile: ForumPublicProfile;

  @OneToMany(() => ForumTopic, (topic) => topic.author)
  forumTopics: ForumTopic[];

  @OneToMany(() => ForumComment, (comment) => comment.author)
  forumComments: ForumComment[];

  @OneToMany(() => ForumTopicWatcher, (watcher) => watcher.user)
  forumTopicWatchers: ForumTopicWatcher[];

  @OneToMany(() => ForumTopicReadState, (readState) => readState.user)
  forumTopicReadStates: ForumTopicReadState[];

  @OneToMany(() => ForumNotification, (notification) => notification.user)
  forumNotifications: ForumNotification[];

  @OneToMany(() => ForumNotification, (notification) => notification.actor)
  forumNotificationActions: ForumNotification[];

  @OneToMany(() => ForumReaction, (reaction) => reaction.user)
  forumReactions: ForumReaction[];

  @OneToMany(() => ForumBookmark, (bookmark) => bookmark.user)
  forumBookmarks: ForumBookmark[];

  @OneToMany(() => ForumReport, (report) => report.reporter)
  forumReports: ForumReport[];

  @OneToMany(() => ForumReport, (report) => report.reviewer)
  reviewedForumReports: ForumReport[];

  @OneToMany(() => ForumModerationLog, (log) => log.moderator)
  forumModerationLogs: ForumModerationLog[];

  @OneToMany(() => ForumMention, (mention) => mention.mentionedUser)
  forumMentions: ForumMention[];

  @OneToMany(() => ForumMention, (mention) => mention.mentionedByUser)
  forumMentionsCreated: ForumMention[];

  @OneToMany(() => ForumView, (view) => view.user)
  forumViews: ForumView[];

  @OneToMany(() => ForumConversation, (conversation) => conversation.userOne)
  forumConversationsAsUserOne: ForumConversation[];

  @OneToMany(() => ForumConversation, (conversation) => conversation.userTwo)
  forumConversationsAsUserTwo: ForumConversation[];

  @OneToMany(() => ForumMessage, (message) => message.sender)
  forumSentMessages: ForumMessage[];

  @OneToMany(() => ForumMessage, (message) => message.recipient)
  forumReceivedMessages: ForumMessage[];

  @OneToMany(() => ForumUserBlock, (block) => block.blocker)
  forumBlockedUsers: ForumUserBlock[];

  @OneToMany(() => ForumUserBlock, (block) => block.blockedUser)
  forumBlockedByUsers: ForumUserBlock[];

  @Index('idx_users_last_active_at')
  @Column({
    type: 'timestamptz',
    nullable: true,
    default: () => 'CURRENT_TIMESTAMP',
  })
  lastActiveAt?: Date | null;

  @Index('idx_users_inactivity_warned_at')
  @Column({ type: 'timestamptz', nullable: true })
  inactivityWarnedAt: Date | null;

  @Index('idx_users_scheduled_deletion_at')
  @Column({ type: 'timestamptz', nullable: true })
  scheduledDeletionAt: Date | null;

  @Index('idx_users_created_at')
  @CreateDateColumn()
  createdAt: Date;

  @UpdateDateColumn()
  updatedAt: Date;
}
